<?php foreach($filas as $f): ?><tr><td><a href="/ventas/detalle?id=<?= (int)$f['id'] ?>">#<?= (int)$f['id'] ?></a><small><?= s($f['creado_en']) ?></small></td><td><?= s($f['comprador_nombre']) ?></td><td><?= $f['cita_id']?'Cita #'.(int)$f['cita_id']:'Mostrador' ?></td><td><?= s($f['estado']) ?></td><td><?= s($dinero($f['total_centavos'])) ?></td></tr><?php endforeach; ?>
<?php if(!$filas): ?><tr><td colspan="5">No hay ventas en este período.</td></tr><?php endif; ?></tbody></table></div>
<nav class="ops-toolbar" aria-label="Páginas de ventas"><span>Página <?= (int)$pagina ?> de <?= (int)$paginas ?></span><?php foreach(['Anterior'=>$pagina-1,'Siguiente'=>$pagina+1] as $et=>$n):if($n<1||$n>$paginas)continue; ?><a href="/ventas?<?= s(http_build_query(['desde'=>$desde,'hasta'=>$hasta,'pagina'=>$n])) ?>"><?= s($et) ?></a><?php endforeach; ?></nav>
